from typing import List
from dataiku.llm.python.custom.base_model import BaseModel
from dataiku.llm.python.processing import _NotImplementedError
from dataiku.llm.python.types import RerankingQuery, RerankingResponse, RerankingSettings
from dataiku.llm.tracing import SpanBuilder

class BaseRerankingModel(BaseModel):
    """The base interface for a reranking model"""

    def process(self, query: RerankingQuery, settings: RerankingSettings, trace: SpanBuilder) -> RerankingResponse:
        raise _NotImplementedError

    async def aprocess(self, query: RerankingQuery, settings: RerankingSettings, trace: SpanBuilder) -> RerankingResponse:
        raise _NotImplementedError
